/**
 * I-016 A (docs/claude/2026-11-03-listen-kind.md): synthetic sound for the "is it music" tests and the evaluation script.
 * Everything here is generated by the program (or read from a WAV the evaluation made with Windows SAPI); no real song,
 * show or recording, and no capture of this computer's sound.
 *
 * `analyserSamples` turns PCM into exactly what the pet window's stage receives from the capture path (src/ui/SystemAudio.ts):
 * an AnalyserNode with fftSize 2048 and smoothingTimeConstant 0.65, read on requestAnimationFrame at most every 1/30 s
 * (so the real ~30 Hz with drops to 20 Hz), the RMS of the last 2048 samples, and the 40–180 / 180–2000 / 2000–8000 Hz
 * band amplitudes of the Blackman-windowed, 1/N-normalised, time-smoothed spectrum (Web Audio's analyser definition).
 */
import { readFileSync } from 'node:fs';
import type { MusicEnergySample } from '../../src/stage/music-dance';

export const RATE = 48_000;

/** Deterministic PRNG (mulberry32). */
export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ------------------------------------------------------------------ the analyser

const FFT = 2048;
const blackman = Float64Array.from({ length: FFT }, (_, n) => 0.42 - 0.5 * Math.cos(2 * Math.PI * n / FFT) + 0.08 * Math.cos(4 * Math.PI * n / FFT));
const bitrev = (() => {
  const out = new Uint32Array(FFT), bits = Math.log2(FFT);
  for (let i = 0; i < FFT; i++) { let r = 0; for (let b = 0; b < bits; b++) r |= ((i >> b) & 1) << (bits - 1 - b); out[i] = r; }
  return out;
})();
const cosT = Float64Array.from({ length: FFT / 2 }, (_, i) => Math.cos(-2 * Math.PI * i / FFT));
const sinT = Float64Array.from({ length: FFT / 2 }, (_, i) => Math.sin(-2 * Math.PI * i / FFT));

function fftMagnitude(input: Float64Array, out: Float64Array): void {
  const re = new Float64Array(FFT), im = new Float64Array(FFT);
  for (let i = 0; i < FFT; i++) re[bitrev[i]!] = input[i]!;
  for (let size = 2; size <= FFT; size *= 2) {
    const half = size / 2, step = FFT / size;
    for (let start = 0; start < FFT; start += size) {
      for (let j = 0; j < half; j++) {
        const c = cosT[j * step]!, s = sinT[j * step]!, a = start + j, b = a + half;
        const tr = re[b]! * c - im[b]! * s, ti = re[b]! * s + im[b]! * c;
        re[b] = re[a]! - tr; im[b] = im[a]! - ti; re[a] = re[a]! + tr; im[a] = im[a]! + ti;
      }
    }
  }
  for (let k = 0; k < FFT / 2; k++) out[k] = Math.hypot(re[k]!, im[k]!) / FFT;
}

export interface AnalyserOptions {
  /** Display refresh (requestAnimationFrame) rate; samples are read when at least 1/30 s passed. Default 60. */
  refreshHz?: number;
  /** ± jitter of each display callback (ms), deterministic. Default 2. */
  jitterMs?: number;
  /** Seconds added to every sample time (the stage's clock does not start at 0). */
  offset?: number;
  seed?: number;
}

/** PCM (mono, RATE) → the stage's MusicEnergySample stream, as SystemAudio.ts computes it. */
export function analyserSamples(pcm: Float32Array, options: AnalyserOptions = {}): MusicEnergySample[] {
  const refresh = options.refreshHz ?? 60, jitter = options.jitterMs ?? 2, random = rng(options.seed ?? 7);
  const smoothed = new Float64Array(FFT / 2), magnitude = new Float64Array(FFT / 2), frame = new Float64Array(FFT);
  const out: MusicEnergySample[] = [];
  const step = RATE / FFT;
  const band = (from: number, to: number) => {
    let power = 0;
    for (let bin = Math.max(1, Math.ceil(from / step)); bin < FFT / 2 && bin * step < to; bin++) {
      const db = smoothed[bin]! > 0 ? 20 * Math.log10(smoothed[bin]!) : -Infinity;
      const amplitude = Number.isFinite(db) ? Math.pow(10, db / 20) : 0;
      power += amplitude * amplitude;
    }
    return Math.max(0, Math.min(1, Math.sqrt(power)));
  };
  let lastAt = -Infinity;
  for (let i = 1; ; i++) {
    const now = i * 1000 / refresh + (random() * 2 - 1) * jitter;
    const end = Math.floor(now / 1000 * RATE);
    if (end > pcm.length) break;
    if ((now - lastAt) / 1000 < 1 / 30) continue;
    lastAt = now;
    let power = 0;
    for (let n = 0; n < FFT; n++) {
      const value = end - FFT + n >= 0 ? pcm[end - FFT + n]! : 0;
      power += value * value; frame[n] = value * blackman[n]!;
    }
    fftMagnitude(frame, magnitude);
    for (let k = 0; k < FFT / 2; k++) smoothed[k] = 0.65 * smoothed[k]! + 0.35 * magnitude[k]!;
    out.push({ time: now / 1000 + (options.offset ?? 0), rms: Math.min(1, Math.sqrt(power / FFT)),
      low: band(40, 180), mid: band(180, 2000), high: band(2000, 8000) });
  }
  return out;
}

// ------------------------------------------------------------------ building blocks

export const seconds = (s: number) => new Float32Array(Math.round(s * RATE));
export const dbGain = (db: number) => Math.pow(10, db / 20);
export function concat(...parts: Float32Array[]): Float32Array {
  const out = new Float32Array(parts.reduce((sum, part) => sum + part.length, 0));
  let at = 0; for (const part of parts) { out.set(part, at); at += part.length; }
  return out;
}
/** a + b·gain, as long as the longer one (b loops if it is shorter). */
export function mix(a: Float32Array, b: Float32Array, gainDb = 0): Float32Array {
  const out = new Float32Array(Math.max(a.length, b.length)), g = dbGain(gainDb);
  for (let i = 0; i < out.length; i++) out[i] = (a[i] ?? 0) + (b.length ? b[i % b.length]! * g : 0);
  return out;
}
export function rmsOf(pcm: Float32Array): number { let p = 0; for (const v of pcm) p += v * v; return Math.sqrt(p / Math.max(1, pcm.length)); }
/** Scale to a target RMS (0..1 full scale). */
export function level(pcm: Float32Array, target: number): Float32Array {
  const r = rmsOf(pcm), g = r > 0 ? target / r : 0, out = new Float32Array(pcm.length);
  for (let i = 0; i < pcm.length; i++) out[i] = Math.max(-1, Math.min(1, pcm[i]! * g));
  return out;
}
export function noise(s: number, seed: number, amplitude = 0.01): Float32Array {
  const out = seconds(s), random = rng(seed);
  for (let i = 0; i < out.length; i++) out[i] = (random() * 2 - 1) * amplitude;
  return out;
}

const midi = (note: number) => 440 * Math.pow(2, (note - 69) / 12);
/** One partial-rich tone added into `out` from `start` for `length` samples with a soft attack and release. */
function addTone(out: Float32Array, start: number, length: number, freq: number, amp: number, attack = 0.01, release = 0.05, partials = 4): void {
  const a = Math.max(1, Math.round(attack * RATE)), r = Math.max(1, Math.round(release * RATE));
  for (let n = 0; n < length && start + n < out.length; n++) {
    if (start + n < 0) continue;
    const env = Math.min(1, n / a, (length - n) / r);
    let v = 0;
    for (let p = 1; p <= partials; p++) v += Math.sin(2 * Math.PI * freq * p * n / RATE) / (p * p);
    out[start + n]! += v * amp * env;
  }
}

/** A song with drums: kick on every beat, snare on 2 and 4, closed hi-hat on eighths, a bass line and chords per bar. */
export function drumSong(s: number, options: { bpm?: number; seed?: number; swing?: number; chords?: boolean } = {}): Float32Array {
  const bpm = options.bpm ?? 112, beat = 60 / bpm, random = rng(options.seed ?? 1), out = seconds(s);
  const progression = [[57, 60, 64], [53, 57, 60], [48, 52, 55], [55, 59, 62]];
  for (let b = 0; b * beat < s; b++) {
    const at = Math.round(b * beat * RATE), bar = Math.floor(b / 4);
    // kick: a falling sine
    for (let n = 0; n < 0.18 * RATE && at + n < out.length; n++) {
      const t = n / RATE, f = 50 + 90 * Math.exp(-t * 30);
      out[at + n]! += Math.sin(2 * Math.PI * f * t) * Math.exp(-t * 18) * 0.55;
    }
    if (b % 4 === 1 || b % 4 === 3) for (let n = 0; n < 0.15 * RATE && at + n < out.length; n++) {
      const t = n / RATE; out[at + n]! += ((random() * 2 - 1) * 0.6 + Math.sin(2 * Math.PI * 190 * t) * 0.4) * Math.exp(-t * 25) * 0.35;
    }
    for (const half of [0, 0.5]) {
      const h = Math.round((b + half + (half ? options.swing ?? 0 : 0)) * beat * RATE);
      let prev = 0;
      for (let n = 0; n < 0.05 * RATE && h + n < out.length; n++) { const w = random() * 2 - 1, hp = w - prev; prev = w; out[h + n]! += hp * Math.exp(-n / RATE * 80) * 0.08; }
    }
    const chord = progression[bar % progression.length]!;
    addTone(out, at, Math.round(beat * 0.9 * RATE), midi(chord[0]! - 24), 0.22, 0.01, 0.05, 3);
    if (options.chords !== false && b % 4 === 0) for (const note of chord) addTone(out, at, Math.round(beat * 4 * RATE), midi(note), 0.05, 0.02, 0.2, 5);
  }
  return level(out, 0.12);
}

/** Music without drums: slow pads (chords that swell in and out) with a soft melody; nothing percussive. */
export function ambientPad(s: number, options: { seed?: number; chordS?: number; melody?: boolean } = {}): Float32Array {
  const random = rng(options.seed ?? 3), chordS = options.chordS ?? 4, out = seconds(s);
  const progression = [[48, 55, 64, 67], [45, 52, 60, 64], [41, 48, 57, 60], [43, 50, 59, 62]];
  for (let c = 0; c * chordS < s; c++) {
    const at = Math.round(c * chordS * RATE), length = Math.round((chordS + 1.2) * RATE);
    for (const note of progression[c % progression.length]!) addTone(out, at, length, midi(note) * (1 + (random() - 0.5) * 0.002), 0.05, 1.0, 1.2, 6);
  }
  if (options.melody !== false) {
    let t = 0.5;
    while (t < s) {
      const length = 0.6 + random() * 1.4, note = [72, 74, 76, 79, 81][Math.floor(random() * 5)]!;
      addTone(out, Math.round(t * RATE), Math.round(length * RATE), midi(note), 0.03, 0.15, 0.4, 3);
      t += length + random() * 0.3;
    }
  }
  return level(out, 0.08);
}

/**
 * Speech-like sound for unit tests (the evaluation uses Windows SAPI voices instead): voiced syllables with a moving pitch
 * and two formants, unvoiced consonant bursts, short gaps between words and longer pauses between phrases. Not a voice, but
 * the same envelope the analyser sees: 3–6 syllables a second, irregular, with dips and pauses.
 */
export function speechLike(s: number, options: { seed?: number; pitch?: number; rate?: number } = {}): Float32Array {
  const random = rng(options.seed ?? 5), out = seconds(s), base = options.pitch ?? 140, speed = options.rate ?? 1;
  let t = 0.2, phase = 0;
  while (t < s) {
    const words = 2 + Math.floor(random() * 6);
    for (let w = 0; w < words && t < s; w++) {
      const syllables = 1 + Math.floor(random() * 3);
      for (let y = 0; y < syllables && t < s; y++) {
        // consonant burst
        const burst = Math.round((0.02 + random() * 0.05) * RATE / speed), at = Math.round(t * RATE);
        for (let n = 0; n < burst && at + n < out.length; n++) out[at + n]! += (random() * 2 - 1) * 0.05;
        t += burst / RATE;
        // vowel: glottal-ish harmonics shaped by two formants
        const length = (0.08 + random() * 0.18) / speed, start = Math.round(t * RATE), n0 = Math.round(length * RATE);
        const f1 = 300 + random() * 600, f2 = 900 + random() * 1600, pitch = base * (0.85 + random() * 0.35), amp = 0.12 + random() * 0.12;
        for (let n = 0; n < n0 && start + n < out.length; n++) {
          const env = Math.sin(Math.PI * n / n0) ** 0.6, f0 = pitch * (1 + 0.1 * Math.sin(2 * Math.PI * n / n0));
          phase += 2 * Math.PI * f0 / RATE;
          let v = 0;
          for (let h = 1; h <= 18; h++) {
            const f = f0 * h, gain = 1 / (1 + ((f - f1) / 120) ** 2) + 0.6 / (1 + ((f - f2) / 200) ** 2);
            v += Math.sin(phase * h) * gain / Math.sqrt(h);
          }
          out[start + n]! += v * amp * env * 0.3;
        }
        t += length;
      }
      t += (0.04 + random() * 0.12) / speed;
    }
    t += (0.25 + random() * 0.6) / speed;
  }
  return level(out, 0.1);
}

/**
 * A sung line for a synthetic song (SAPI cannot sing): sustained vowels on a scale, each note starting on the beat grid and
 * lasting one or two beats (sometimes a half), with vibrato, a short consonant at each note's start and a breath every
 * couple of bars. The same formant synthesis as speechLike, so the difference to speech is only the timing.
 */
export function sungVocal(s: number, options: { bpm?: number; seed?: number; pitch?: number } = {}): Float32Array {
  const bpm = options.bpm ?? 112, beat = 60 / bpm, random = rng(options.seed ?? 21), out = seconds(s), base = options.pitch ?? 60;
  const scale = [0, 2, 4, 5, 7, 9, 11, 12];
  let b = 1, phase = 0;
  while (b * beat < s) {
    if (b % 8 === 7) { b += 1; continue; } // a breath
    const beats = [0.5, 1, 1, 2, 2][Math.floor(random() * 5)]!, start = Math.round(b * beat * RATE), n0 = Math.round(beats * beat * 0.95 * RATE);
    const f0n = midi(base + scale[Math.floor(random() * scale.length)]!), f1 = 400 + random() * 400, f2 = 1000 + random() * 1200;
    for (let n = 0; n < Math.round(0.03 * RATE) && start + n < out.length; n++) out[start + n]! += (random() * 2 - 1) * 0.03;
    for (let n = 0; n < n0 && start + n < out.length; n++) {
      const env = Math.min(1, n / (0.04 * RATE), (n0 - n) / (0.08 * RATE));
      const f0 = f0n * (1 + 0.012 * Math.sin(2 * Math.PI * 5.5 * n / RATE));
      phase += 2 * Math.PI * f0 / RATE;
      let v = 0;
      for (let h = 1; h <= 14; h++) { const f = f0 * h; v += Math.sin(phase * h) * (1 / (1 + ((f - f1) / 120) ** 2) + 0.6 / (1 + ((f - f2) / 200) ** 2)) / Math.sqrt(h); }
      out[start + n]! += v * env * 0.05;
    }
    b += beats;
  }
  return level(out, 0.1);
}

/** Bursts of synthetic laughter: "ha" pulses (~5 per second) of breathy voiced noise. */
export function laughter(s: number, seed = 11): Float32Array {
  const random = rng(seed), out = seconds(s);
  for (let t = 0.05; t < s - 0.15; t += 0.17 + random() * 0.05) {
    const at = Math.round(t * RATE), n0 = Math.round(0.11 * RATE), f0 = 260 + random() * 60;
    for (let n = 0; n < n0 && at + n < out.length; n++) {
      const env = Math.sin(Math.PI * n / n0);
      out[at + n]! += (Math.sin(2 * Math.PI * f0 * n / RATE) * 0.5 + (random() * 2 - 1) * 0.5) * env * 0.2;
    }
  }
  return level(out, 0.09);
}

/** A 16-bit PCM WAV (mono or stereo, any rate) → mono Float32 at RATE (linear resampling). */
export function readWav(path: string): Float32Array {
  const buffer = readFileSync(path);
  let offset = 12, channels = 1, rate = RATE, bits = 16, data: Buffer | null = null;
  while (offset + 8 <= buffer.length) {
    const id = buffer.toString('ascii', offset, offset + 4), size = buffer.readUInt32LE(offset + 4);
    if (id === 'fmt ') { channels = buffer.readUInt16LE(offset + 10); rate = buffer.readUInt32LE(offset + 12); bits = buffer.readUInt16LE(offset + 22); }
    if (id === 'data') data = buffer.subarray(offset + 8, offset + 8 + size);
    offset += 8 + size + (size % 2);
  }
  if (!data || bits !== 16) throw Error(`${path}: only 16-bit PCM WAV`);
  const frames = Math.floor(data.length / 2 / channels), mono = new Float32Array(frames);
  for (let i = 0; i < frames; i++) { let v = 0; for (let c = 0; c < channels; c++) v += data.readInt16LE((i * channels + c) * 2) / 32768; mono[i] = v / channels; }
  if (rate === RATE) return mono;
  const out = new Float32Array(Math.floor(frames * RATE / rate));
  for (let i = 0; i < out.length; i++) { const x = i * rate / RATE, j = Math.floor(x), f = x - j; out[i] = (mono[j] ?? 0) * (1 - f) + (mono[j + 1] ?? 0) * f; }
  return out;
}
